"""Read-only NAV snapshot of the flagship vault: every call simulated at the same ledger. Nothing signed."""
import json, sys, time, requests
from stellar_sdk import SorobanServer, TransactionBuilder, Account, scval, Network
from stellar_sdk.xdr import SCVal

RPC = "https://soroban-testnet.stellar.org"
s = SorobanServer(RPC)
SRC = "GDGCL46KVU6FR2BU32PUGS7KBQCE6U4375JCR7NHU3PMX5K3O7VXJT7N"
F = "CD73M44EYNZOX7YWPSBMITVPERWNA6ZHDLAZ2XSM4RQM6V4XT7GYXFQH"
POOL = "CCEBVDYM32YNYCVNRXQKDFFPISJJCV557CDZEIRBEE4NCV4KHPQ44HGF"
ORACLE = "CC3ASLC6FIH76EVTMJIC2IAMVUS5Y5JYXI4WM4U5RPEUBPUGCWWSX5EB"
USDC = "CAQCFVLOBK5GIULPNZRGATJJMIZL5BSP7X5YJVMGCPTUEPFM4AVSRCJU"
TRES = "CCOF6WEYQQUFIMR4SEVELW4AGZAOYMGZCYCQVXN7AFGWZXXVEDPXQ5K7"
XLM = "CDLZFC3SYJYDZT7K67VZ75HPJVIEUVNIXF47ZG2FB2RMQQVU2HHGCYSC"
ONE_SHARE = 10**12  # vault shares have 12 decimals

CALLS = [
    ("total_assets", F, "total_assets", []),
    ("convert_to_assets_1_share", F, "convert_to_assets", [scval.to_int128(ONE_SHARE)]),
    ("convert_to_assets_1000_shares", F, "convert_to_assets", [scval.to_int128(1000 * ONE_SHARE)]),
    ("total_supply", F, "total_supply", []),
    ("state", F, "state", []),
    ("holdings", F, "holdings", []),
    ("get_reserve_usdc", POOL, "get_reserve", [scval.to_address(USDC)]),
    ("get_positions_vault", POOL, "get_positions", [scval.to_address(F)]),
    ("mark_tRESERVE", ORACLE, "mark", [scval.to_address(TRES)]),
    ("mark_XLM", ORACLE, "mark", [scval.to_address(XLM)]),
]


def sim(contract, fn, args):
    tx = (TransactionBuilder(Account(SRC, 0), Network.TESTNET_NETWORK_PASSPHRASE, base_fee=100)
          .append_invoke_contract_function_op(contract, fn, args).set_timeout(300).build())
    r = s.simulate_transaction(tx)
    if r.error:
        raise RuntimeError(f"{fn}: {r.error[:400]}")
    x = r.results[0].xdr
    return {"contract": contract, "function": fn, "latest_ledger": r.latest_ledger, "result_xdr": x,
            "decoded": scval.to_native(SCVal.from_xdr(x))}


def ledger_close(seq):
    body = {"jsonrpc": "2.0", "id": 1, "method": "getLedgers", "params": {"startLedger": seq, "pagination": {"limit": 1}}}
    r = requests.post(RPC, json=body, timeout=30).json()
    l = r["result"]["ledgers"][0]
    return {"sequence": l["sequence"], "ledgerCloseTime": l["ledgerCloseTime"],
            "utc": time.strftime("%Y-%m-%dT%H:%M:%SZ", time.gmtime(int(l["ledgerCloseTime"]))), "hash": l["hash"]}


def snapshot():
    for attempt in range(20):
        out = {k: sim(c, f, a) for k, c, f, a in CALLS}
        ledgers = {v["latest_ledger"] for v in out.values()}
        if len(ledgers) == 1:
            seq = ledgers.pop()
            return {"taken_utc": time.strftime("%Y-%m-%dT%H:%M:%SZ", time.gmtime()), "rpc": RPC,
                    "latest_ledger": seq, "ledger": ledger_close(seq), "attempts": attempt + 1, "calls": out}
        time.sleep(0.5)
    raise RuntimeError("could not get all reads at one ledger")


if __name__ == "__main__":
    print(json.dumps(snapshot(), default=str))
